 21	class TSDF3D16
 22	{
 23		
 24	public:
 25	
 26		TSDF3D16(void) 
 27		{
 28			m_maxX = 40;
 29			m_maxY = 40;
 30			m_maxZ = 40;
 31			m_minX = -40;
 32			m_minY = -40;
 33			m_minZ = -10;
 34			m_resolution = 0.05;
 35			m_oneDivRes = 1/m_resolution;
