 42		void setup(float minX, float maxX, 
 43				   float minY, float maxY, 
 44				   float minZ, float maxZ, 
 45				   float resolution, 
 46				   int kernelSize,
 47				   int occMinHits,
 48				   int binsAz,
 49	               int binsEl,
