 51	               std::string distanceMode,
 52				   int maxCells = 50000,
 53				   bool verboseInit = false
 54				   )
 55		{
 56			m_maxX = maxX;
 57			m_maxY = maxY;
 58			m_maxZ = maxZ;
 59			m_minX = minX;
 60			m_minY = minY;
 61			m_minZ = minZ;
 62			m_resolution = resolution;
 63			m_oneDivRes = 1/m_resolution;
 64			m_occMinHits = occMinHits;
 65			m_binsAz = binsAz;
 66	        m_binsEl = binsEl;
 67	        m_numBins = m_binsAz * m_binsEl;
 68	        m_shadowRadiusMd = shadowRadius;
 69	        m_distanceMode = distanceMode;
 70			m_kernelSize = kernelSize;
 71	    	m_kernelRadius = (kernelSize - 1) / 2;
 72	        m_verboseInit = verboseInit;
 73	
 74			initDirectionalKernels();
 75	
 76			// Setup grid
 77			m_grid.setup(m_minX, m_maxX, m_minY, m_maxY, m_minZ, m_maxZ, m_resolution, maxCells);
