108		virtual inline bool isIntoGrid(const float &x, const float &y, const float &z)
109		{
110			return (x > m_minX+1 && y > m_minY+1 && z > m_minZ+1 && x < m_maxX-1 && y < m_maxY-1 && z < m_maxZ-1);
111		}
