113	
114		void loadCloud(std::vector<pcl::PointXYZ> &cloud, float tx, float ty, float tz, float yaw)
115		{
116			std::vector<pcl::PointXYZ> out;
117	
118			float c = cos(yaw);
119			float s = sin(yaw);
120			out.resize(cloud.size());
121			for(uint32_t i=0; i<out.size(); i++)
122			{
123				out[i].x = c*cloud[i].x - s*cloud[i].y + tx;
124				out[i].y = s*cloud[i].x + c*cloud[i].y + ty; 
125				out[i].z = cloud[i].z + tz;
126			}
127			loadCloud(out, Eigen::Vector3f(tx, ty, tz));
128		}
129	
130		void loadCloud(std::vector<pcl::PointXYZ> &cloud, float tx, float ty, float tz, float roll, float pitch, float yaw)
131		{
132			std::vector<pcl::PointXYZ> out;
133	
134			// Get rotation matrix
135			float cr, sr, cp, sp, cy, sy;
136			float r00, r01, r02, r10, r11, r12, r20, r21, r22;
137			sr = sin(roll);
138			cr = cos(roll);
139			sp = sin(pitch);
140			cp = cos(pitch);
141			sy = sin(yaw);
142			cy = cos(yaw);
143			r00 = cy*cp; 	r01 = cy*sp*sr-sy*cr; 	r02 = cy*sp*cr+sy*sr;
144			r10 = sy*cp; 	r11 = sy*sp*sr+cy*cr;	r12 = sy*sp*cr-cy*sr;
145			r20 = -sp;		r21 = cp*sr;			r22 = cp*cr;
146	
147			// Tiltcompensate points 
148			out.resize(cloud.size());
149			for(uint i=0; i<cloud.size(); i++) 
150			{
151				out[i].x = cloud[i].x*r00 + cloud[i].y*r01 + cloud[i].z*r02 + tx;
152				out[i].y = cloud[i].x*r10 + cloud[i].y*r11 + cloud[i].z*r12 + ty;
153				out[i].z = cloud[i].x*r20 + cloud[i].y*r21 + cloud[i].z*r22 + tz;	
154			}
155			loadCloud(out, Eigen::Vector3f(tx, ty, tz));
156		}
157	
158		void loadCloudFiltered(std::vector<pcl::PointXYZ> &cloud,
159	                       float tx, float ty, float tz,
160	                       float roll, float pitch, float yaw,
161	                       float maxAbs)
162		{
163			std::vector<pcl::PointXYZ> out;
164			out.reserve(cloud.size()); 
165	
166			// Matriz de rotación precalculada (radianes)
167			const float sr = std::sin(roll),  cr = std::cos(roll);
168			const float sp = std::sin(pitch), cp = std::cos(pitch);
169			const float sy = std::sin(yaw),   cy = std::cos(yaw);
170	
171			const float r00 =  cy*cp;           const float r01 =  cy*sp*sr - sy*cr;  const float r02 =  cy*sp*cr + sy*sr;
172			const float r10 =  sy*cp;           const float r11 =  sy*sp*sr + cy*cr;  const float r12 =  sy*sp*cr - cy*sr;
173			const float r20 = -sp;              const float r21 =  cp*sr;              const float r22 =  cp*cr;
174	
175			for (std::size_t i = 0; i < cloud.size(); ++i)
176			{
177				const float ix = cloud[i].x;
178				const float iy = cloud[i].y;
179				const float iz = cloud[i].z;
180	
181				// Sólo calcular x', y' para el filtro rápido
182				const float xw = ix*r00 + iy*r01 + iz*r02 + tx;
183				const float yw = ix*r10 + iy*r11 + iz*r12 + ty;
184	
185				// Filtro por ventana rectangular en XY (Chebyshev / AABB)
186				if (std::fabs(xw) <= maxAbs && std::fabs(yw) <= maxAbs)
187				{
188					// Calcula z' sólo si el punto pasa el filtro
189					const float zw = ix*r20 + iy*r21 + iz*r22 + tz;
190	
191					pcl::PointXYZ p;
192					p.x = xw; p.y = yw; p.z = zw;
193					out.push_back(p);
194				}
195			}
196			loadCloud(out, Eigen::Vector3f(tx, ty, tz));
197		}
