200		void loadCloud(std::vector<pcl::PointXYZ> &cloud, const Eigen::Vector3f &sensor_pos_world)
201		{	
202			// Allocate required submetric cells
203			for(uint32_t i=0; i<cloud.size(); i++)
204			{
205				for(float z=cloud[i].z-1; z<=cloud[i].z+1; z+=1)
206					for(float y=cloud[i].y-1; y<=cloud[i].y+1; y+=1)
207						for(float x=cloud[i].x-1; x<=cloud[i].x+1; x+=1)
208							if(isIntoGrid(x, y, z))
209								m_grid.allocCell(x, y, z);
210			}
211	
212			// Applies the pre-computed kernel to all grid cells centered in the cloud points 
213			const float step = m_kernelRadius * m_resolution;
214	
215			#pragma omp parallel for num_threads(16) shared(m_dirKernels, m_grid) 
216			for(uint32_t i=0; i<cloud.size(); i++)
217			{
218				
219				if(!isIntoGrid(cloud[i].x - step*2, cloud[i].y - step*2, cloud[i].z - step*2) || 
220				   !isIntoGrid(cloud[i].x + step*2, cloud[i].y + step*2, cloud[i].z + step*2))
221					continue;
222	
223				// Select kernel by ray direction
224				Eigen::Vector3f point_world(cloud[i].x, cloud[i].y, cloud[i].z);
225	        	Eigen::Vector3f dir = point_world - sensor_pos_world;
226				const DirectionalKernel& DK = m_dirKernels[dirToBin(dir)];
227	
228				int xi, yi, zi, k = 0;
229				float x, y, z;
230				for(zi=0, z=cloud[i].z-step; zi<m_kernelSize; zi++, z+=m_resolution)
231					for(yi=0, y=cloud[i].y-step; yi<m_kernelSize; yi++, y+=m_resolution){
232						GRID16::Iterator it = m_grid.getIterator(cloud[i].x-step,y,z);
233						for(xi=0, x=cloud[i].x-step; xi<m_kernelSize; xi++, x+=m_resolution,++it, ++k)
234						{						
235							VoxelData &v = *it;
236							uint16_t old_mask = v.d;
237							uint16_t new_mask = old_mask & DK.distance_masks[k];
238							if (new_mask != old_mask) v.d = new_mask;
239	
240							if(DK.signs[k] == 0 && v.hits < m_occMinHits) 
241							{
242								++v.hits;
243								if (v.hits == m_occMinHits)
244									v.s &= uint8_t(~0x01);
245							}
246						}
247					}
248			}
249			#pragma omp barrier
250		}
251	
252		inline TrilinearParams computeDistInterpolation(const double &x, const double &y, const double &z)
253		{
254			TrilinearParams r;
255	
256			if(isIntoGrid(x, y, z))
257			{
258	
259				// Get neightbour values to compute trilinear interpolation
260				float c000, c001, c010, c011, c100, c101, c110, c111;
261				c000 = std::bitset<16>(m_grid.read(x, y, z).d).count(); 
262				c001 = std::bitset<16>(m_grid.read(x, y, z+m_resolution).d).count(); 
263				c010 = std::bitset<16>(m_grid.read(x, y+m_resolution, z).d).count(); 
264				c011 = std::bitset<16>(m_grid.read(x, y+m_resolution, z+m_resolution).d).count();  
265				c100 = std::bitset<16>(m_grid.read(x+m_resolution, y, z).d).count();  
266				c101 = std::bitset<16>(m_grid.read(x+m_resolution, y, z+m_resolution).d).count();  
267				c110 = std::bitset<16>(m_grid.read(x+m_resolution, y+m_resolution, z).d).count();  
268				c111 = std::bitset<16>(m_grid.read(x+m_resolution, y+m_resolution, z+m_resolution).d).count(); 
269	
270				// Compute trilinear parameters
271				const float div = -m_oneDivRes*m_oneDivRes*m_oneDivRes;
272				float x0, y0, z0, x1, y1, z1;
273				x0 = ((int)(x*m_oneDivRes))*m_resolution;
274				if(x0<0)
275					x0 -= m_resolution; 
276				x1 = x0+m_resolution;
277				y0 = ((int)(y*m_oneDivRes))*m_resolution;
278				if(y0<0)
279					y0 -= m_resolution;
280				y1 = y0+m_resolution;
281				z0 = ((int)(z*m_oneDivRes))*m_resolution;
282				if(z0<0)
283					z0 -= m_resolution;
284				z1 = z0+m_resolution;
285				r.a0 = (-c000*x1*y1*z1 + c001*x1*y1*z0 + c010*x1*y0*z1 - c011*x1*y0*z0 
286				+ c100*x0*y1*z1 - c101*x0*y1*z0 - c110*x0*y0*z1 + c111*x0*y0*z0)*div;
287				r.a1 = (c000*y1*z1 - c001*y1*z0 - c010*y0*z1 + c011*y0*z0
288				- c100*y1*z1 + c101*y1*z0 + c110*y0*z1 - c111*y0*z0)*div;
289				r.a2 = (c000*x1*z1 - c001*x1*z0 - c010*x1*z1 + c011*x1*z0 
290				- c100*x0*z1 + c101*x0*z0 + c110*x0*z1 - c111*x0*z0)*div;
291				r.a3 = (c000*x1*y1 - c001*x1*y1 - c010*x1*y0 + c011*x1*y0 
292				- c100*x0*y1 + c101*x0*y1 + c110*x0*y0 - c111*x0*y0)*div;
293				r.a4 = (-c000*z1 + c001*z0 + c010*z1 - c011*z0 + c100*z1 
294				- c101*z0 - c110*z1 + c111*z0)*div;
295				r.a5 = (-c000*y1 + c001*y1 + c010*y0 - c011*y0 + c100*y1 
296				- c101*y1 - c110*y0 + c111*y0)*div;
297				r.a6 = (-c000*x1 + c001*x1 + c010*x1 - c011*x1 + c100*x0 
298				- c101*x0 - c110*x0 + c111*x0)*div;
299				r.a7 = (c000 - c001 - c010 + c011 - c100
300				+ c101 + c110 - c111)*div;
301			}
302	
303			return r;
304		}
305	
306	protected:
307	
308		// Grid parameters
309		GRID16 m_grid;
310		float m_maxX, m_maxY, m_maxZ;
311		float m_minX, m_minY, m_minZ;
312		float m_resolution, m_oneDivRes;	
313		int m_occMinHits;
314		int m_kernelSize;
315	    int m_kernelRadius;
316		int m_binsAz;
317	    int m_binsEl;
318	    int m_numBins;
319	    int m_shadowRadiusMd;
320	    std::string m_distanceMode;
321	    bool m_verboseInit{false};
322	
323		// Directional kernels
324		std::vector<DirectionalKernel> m_dirKernels;
325		inline int dirToBin(const Eigen::Vector3f &v) const;
326		void initDirectionalKernels();
327	
328		std::map<int, uint16_t> m_r_squared_to_mask16;
329	
330	};
331	
332	// Map direction to bin index (azimuth × elevation)
333	inline int TSDF3D16::dirToBin(const Eigen::Vector3f &v) const
334	{
335		float az = std::atan2(v.y(), v.x());
336		if (az < 0) 
337		{
338			az += 2.0f*M_PI;
339		}
340	
341		float el  = std::asin(v.z() / v.norm());
342		int   baz = int(az * m_binsAz / (2.0f*M_PI));
343	    int   bel = int((el + M_PI/2) * m_binsEl / M_PI);
344	
345	    bel = std::clamp(bel, 0, m_binsEl - 1);
346	    baz = std::clamp(baz, 0, m_binsAz - 1);
347	
348	    return bel*m_binsAz + baz;    
349	}
350	
351	
352	inline void TSDF3D16::initDirectionalKernels()
353	{
354	    if (m_distanceMode == "L2")
355	    {
356	        if (m_verboseInit) std::cout << "--- [TSDF3D16] Generating 16-bit L2 (Euclidean) distance LUT..." << std::endl;
357	        if (m_r_squared_to_mask16.empty())
358	        {
359	            std::set<int> unique_r_squared;
360	            for (int z = -m_kernelRadius; z <= m_kernelRadius; ++z)
361	                for (int y = -m_kernelRadius; y <= m_kernelRadius; ++y)
362	                    for (int x = -m_kernelRadius; x <= m_kernelRadius; ++x)
363	                    {
364	                        unique_r_squared.insert(x*x + y*y + z*z);
365	                    }
366	
367	            m_r_squared_to_mask16.clear();
368	            uint16_t rank = 0;
369	
370	            if (m_verboseInit) std::cout << "---Rank -> L2 Distance (Voxels)" << std::endl;
371	            for (int r2 : unique_r_squared)
372	            {
373	                uint16_t mask;
374	                if (rank == 0)      { mask = 0u; }
375	                else if (rank < 16) { mask = (0xFFFFu >> (16 - rank)); }
376	                else                { mask = 0xFFFFu; }
377	                m_r_squared_to_mask16[r2] = mask;
378	                if (m_verboseInit)
379	                {
380	                    float l2_dist = std::sqrt(static_cast<float>(r2));
381	                    std::cout << std::setw(5) << rank << " -> " << l2_dist;
382	                    if (rank >= 16) { std::cout << " (Truncated to 16 bits)"; }
383	                    std::cout << std::endl;
384	                }
385	                rank++;
386	            }
387	        }
388	    }
389	    else if (m_distanceMode == "L1")
390	    {
391	        if (m_verboseInit) std::cout << "--- [TSDF3D16] Using 16-bit L1 (Manhattan) distance masks." << std::endl;
392	    }
393	    else
394	    {
395	    	std::cerr << "[TSDF3D16] Warning: distance_mode '" << m_distanceMode << "' not recognized. Defaulting to 'L1'." << std::endl;
396	    	m_distanceMode = "L1";
397	    }
398	
399		// --- Kernel Generation ---
400	    m_dirKernels.resize(m_numBins);
401	
402		const int kernel_total_voxels = m_kernelSize * m_kernelSize * m_kernelSize;
403	
404	    auto binToDir = [&](int az,int el) // <-- Añadido [&] para capturar 'this'
405	    {            
406	        float azr = (az+0.5f)*2.0f*M_PI / m_binsAz;
407	        float elr = (-M_PI/2)+ (el+0.5f)*M_PI / m_binsEl;
408	        float c   = cosf(elr);
409	        return Eigen::Vector3f(c*cosf(azr), c*sinf(azr), sinf(elr));
410	    };
411		
412	    for(int el=0; el < m_binsEl; ++el) 
413	    for(int az=0; az < m_binsAz; ++az) 
414	    {
415	        DirectionalKernel& DK = m_dirKernels[el*m_binsAz+az]; 
416	        Eigen::Vector3f dir = binToDir(az,el).normalized();
417	
418			DK.distance_masks.resize(kernel_total_voxels);
419	        DK.signs.resize(kernel_total_voxels);
420			
421	        int k=0;
422	        for(int z=-m_kernelRadius;z<=m_kernelRadius;++z) 
423	        for(int y=-m_kernelRadius;y<=m_kernelRadius;++y)
424	        for(int x=-m_kernelRadius;x<=m_kernelRadius;++x,++k)
425	        {       
426	            const float R_E = float(m_shadowRadiusMd); 
427	            float re2 = float(x*x + y*y + z*z); 
428	
429				// The Distance Mode "switch"
430	            if (m_distanceMode == "L1")
431	            {
432	                int l1_dist = std::abs(x) + std::abs(y) + std::abs(z);
433	                int   rd  = std::min(16, l1_dist);         
434	                uint16_t mask = (rd == 0) ? 0u : (0xFFFFu >> (16 - rd));
435	                DK.distance_masks[k] = mask;
436	            }
437	            else // "L2"
438	            {
439	                int r2_int = x*x + y*y + z*z; 
440	                DK.distance_masks[k] = m_r_squared_to_mask16[r2_int];
441	            }
442	            
443	            bool behind   = dir.dot(Eigen::Vector3f(x,y,z)) >= 0.0f;     
444	            const bool at_hit = (x == 0 && y == 0 && z == 0);
445	            bool inShadow = behind && (re2 <= R_E*R_E);                 
446	            DK.signs[k]   = (at_hit || inShadow) ? 0 : 1; 
447	        }
448	
449			// --- Kernel preview (only with verbose_init) ---
450	        int az_ray_from_left = 0; // Azimuth bin 0 corresponde a +X
451	        int el_horizontal = m_binsEl / 2; // Bin de elevación central (horizontal)
452	
453	        if (m_verboseInit && el == el_horizontal && az == az_ray_from_left)
454	        {
455	            std::cout << "\n--- Kernel preview (+X Ray) [Z=0 Slice] ---" << std::endl;
456	            std::cout << "--- Rank " << m_distanceMode << " | Shadow Radius: " << m_shadowRadiusMd << " ---" << std::endl;
457	            std::cout << "Format: [Rank][Sign] (#=Occupied/Shadow, .=Free)\n" << std::endl;
458	            std::cout << " (Y+) \n" << "  ^ \n" << "  | \n";
459	            
460	            int z_central = 0;
461	            int iz = z_central + m_kernelRadius;
462	            
463	            for(int y = m_kernelRadius; y >= -m_kernelRadius; --y) { 
464	                int iy = y + m_kernelRadius; 
465	                std::cout << std::setw(2) << y << " | "; 
466	                for(int x = -m_kernelRadius; x <= m_kernelRadius; ++x) { 
467	                    int ix = x + m_kernelRadius;
468	                    int k_idx = (iz * m_kernelSize * m_kernelSize) + (iy * m_kernelSize) + ix;
469	                    uint16_t mask = DK.distance_masks[k_idx];
470	                    int rank = std::bitset<16>(mask).count();
471	                    uint8_t sign = DK.signs[k_idx];
472	                    char sign_char = (sign == 0) ? '#' : '.';
473	                    std::cout << " " << std::setw(2) << rank << sign_char;
474	                }
475	                std::cout << std::endl; 
476	            }
477	            
478	            std::cout << "   " << std::string(60, '-') << "> (X+)" << std::endl;
479	            std::cout << "     ";
480	            for(int x = -m_kernelRadius; x <= m_kernelRadius; ++x) {
481	                std::cout << " " << std::setw(3) << x;
482	            }
483	            std::cout << "\n---------------------------------------------------------------------\n" << std::endl;
484	        }
485	    }
486	}
487	
488	#endif

