200		void loadCloud(std::vector<pcl::PointXYZ> &cloud, const Eigen::Vector3f &sensor_pos_world)
201		{	
202			// Allocate required submetric cells
203			for(uint32_t i=0; i<cloud.size(); i++)
204			{
205				for(float z=cloud[i].z-1; z<=cloud[i].z+1; z+=1)
206					for(float y=cloud[i].y-1; y<=cloud[i].y+1; y+=1)
207						for(float x=cloud[i].x-1; x<=cloud[i].x+1; x+=1)
208							if(isIntoGrid(x, y, z))
209								m_grid.allocCell(x, y, z);
210			}
211	
212			// Applies the pre-computed kernel to all grid cells centered in the cloud points 
213			const float step = m_kernelRadius * m_resolution;
214	
215			#pragma omp parallel for num_threads(16) shared(m_dirKernels, m_grid) 
216			for(uint32_t i=0; i<cloud.size(); i++)
217			{
218				
219				if(!isIntoGrid(cloud[i].x - step*2, cloud[i].y - step*2, cloud[i].z - step*2) || 
220				   !isIntoGrid(cloud[i].x + step*2, cloud[i].y + step*2, cloud[i].z + step*2))
221					continue;
222	
223				// Select kernel by ray direction
224				Eigen::Vector3f point_world(cloud[i].x, cloud[i].y, cloud[i].z);
225	        	Eigen::Vector3f dir = point_world - sensor_pos_world;
226				const DirectionalKernel& DK = m_dirKernels[dirToBin(dir)];
227	
228				int xi, yi, zi, k = 0;
229				float x, y, z;
230				for(zi=0, z=cloud[i].z-step; zi<m_kernelSize; zi++, z+=m_resolution)
231					for(yi=0, y=cloud[i].y-step; yi<m_kernelSize; yi++, y+=m_resolution){
232						GRID16::Iterator it = m_grid.getIterator(cloud[i].x-step,y,z);
233						for(xi=0, x=cloud[i].x-step; xi<m_kernelSize; xi++, x+=m_resolution,++it, ++k)
234						{						
235							VoxelData &v = *it;
236							uint16_t old_mask = v.d;
237							uint16_t new_mask = old_mask & DK.distance_masks[k];
238							if (new_mask != old_mask) v.d = new_mask;
239	
240							if(DK.signs[k] == 0 && v.hits < m_occMinHits) 
241							{
242								++v.hits;
243								if (v.hits == m_occMinHits)
244									v.s &= uint8_t(~0x01);
245							}
246						}
247					}
248			}
249			#pragma omp barrier
250		}
251	
252		inline TrilinearParams computeDistInterpolation(const double &x, const double &y, const double &z)
253		{
254			TrilinearParams r;
255	
256			if(isIntoGrid(x, y, z))
257			{
258	
259				// Get neightbour values to compute trilinear interpolation
260				float c000, c001, c010, c011, c100, c101, c110, c111;
261				c000 = std::bitset<16>(m_grid.read(x, y, z).d).count(); 
262				c001 = std::bitset<16>(m_grid.read(x, y, z+m_resolution).d).count(); 
263				c010 = std::bitset<16>(m_grid.read(x, y+m_resolution, z).d).count(); 
264				c011 = std::bitset<16>(m_grid.read(x, y+m_resolution, z+m_resolution).d).count();  
265				c100 = std::bitset<16>(m_grid.read(x+m_resolution, y, z).d).count();  
266				c101 = std::bitset<16>(m_grid.read(x+m_resolution, y, z+m_resolution).d).count();  
267				c110 = std::bitset<16>(m_grid.read(x+m_resolution, y+m_resolution, z).d).count();  
268				c111 = std::bitset<16>(m_grid.read(x+m_resolution, y+m_resolution, z+m_resolution).d).count(); 
269	
270				// Compute trilinear parameters
271				const float div = -m_oneDivRes*m_oneDivRes*m_oneDivRes;
272				float x0, y0, z0, x1, y1, z1;
273				x0 = ((int)(x*m_oneDivRes))*m_resolution;
274				if(x0<0)
275					x0 -= m_resolution; 
276				x1 = x0+m_resolution;
277				y0 = ((int)(y*m_oneDivRes))*m_resolution;
278				if(y0<0)
279					y0 -= m_resolution;
280				y1 = y0+m_resolution;
281				z0 = ((int)(z*m_oneDivRes))*m_resolution;
282				if(z0<0)
283					z0 -= m_resolution;
284				z1 = z0+m_resolution;
285				r.a0 = (-c000*x1*y1*z1 + c001*x1*y1*z0 + c010*x1*y0*z1 - c011*x1*y0*z0 
286				+ c100*x0*y1*z1 - c101*x0*y1*z0 - c110*x0*y0*z1 + c111*x0*y0*z0)*div;
287				r.a1 = (c000*y1*z1 - c001*y1*z0 - c010*y0*z1 + c011*y0*z0
288				- c100*y1*z1 + c101*y1*z0 + c110*y0*z1 - c111*y0*z0)*div;
289				r.a2 = (c000*x1*z1 - c001*x1*z0 - c010*x1*z1 + c011*x1*z0 
290				- c100*x0*z1 + c101*x0*z0 + c110*x0*z1 - c111*x0*z0)*div;
291				r.a3 = (c000*x1*y1 - c001*x1*y1 - c010*x1*y0 + c011*x1*y0 
292				- c100*x0*y1 + c101*x0*y1 + c110*x0*y0 - c111*x0*y0)*div;
293				r.a4 = (-c000*z1 + c001*z0 + c010*z1 - c011*z0 + c100*z1 
294				- c101*z0 - c110*z1 + c111*z0)*div;
295				r.a5 = (-c000*y1 + c001*y1 + c010*y0 - c011*y0 + c100*y1 
296				- c101*y1 - c110*y0 + c111*y0)*div;
297				r.a6 = (-c000*x1 + c001*x1 + c010*x1 - c011*x1 + c100*x0 
298				- c101*x0 - c110*x0 + c111*x0)*div;
299				r.a7 = (c000 - c001 - c010 + c011 - c100
300				+ c101 + c110 - c111)*div;
301			}
302	
303			return r;
304		}
