332	// Map direction to bin index (azimuth × elevation)
333	inline int TSDF3D16::dirToBin(const Eigen::Vector3f &v) const
334	{
335		float az = std::atan2(v.y(), v.x());
336		if (az < 0) 
337		{
338			az += 2.0f*M_PI;
339		}
340	
341		float el  = std::asin(v.z() / v.norm());
342		int   baz = int(az * m_binsAz / (2.0f*M_PI));
343	    int   bel = int((el + M_PI/2) * m_binsEl / M_PI);
344	
345	    bel = std::clamp(bel, 0, m_binsEl - 1);
346	    baz = std::clamp(baz, 0, m_binsAz - 1);
347	
348	    return bel*m_binsAz + baz;    
349	}
