351	
352	inline void TSDF3D16::initDirectionalKernels()
353	{
354	    if (m_distanceMode == "L2")
355	    {
356	        if (m_verboseInit) std::cout << "--- [TSDF3D16] Generating 16-bit L2 (Euclidean) distance LUT..." << std::endl;
357	        if (m_r_squared_to_mask16.empty())
358	        {
359	            std::set<int> unique_r_squared;
360	            for (int z = -m_kernelRadius; z <= m_kernelRadius; ++z)
361	                for (int y = -m_kernelRadius; y <= m_kernelRadius; ++y)
362	                    for (int x = -m_kernelRadius; x <= m_kernelRadius; ++x)
363	                    {
364	                        unique_r_squared.insert(x*x + y*y + z*z);
365	                    }
366	
367	            m_r_squared_to_mask16.clear();
368	            uint16_t rank = 0;
369	
370	            if (m_verboseInit) std::cout << "---Rank -> L2 Distance (Voxels)" << std::endl;
371	            for (int r2 : unique_r_squared)
372	            {
373	                uint16_t mask;
374	                if (rank == 0)      { mask = 0u; }
375	                else if (rank < 16) { mask = (0xFFFFu >> (16 - rank)); }
376	                else                { mask = 0xFFFFu; }
377	                m_r_squared_to_mask16[r2] = mask;
378	                if (m_verboseInit)
379	                {
380	                    float l2_dist = std::sqrt(static_cast<float>(r2));
381	                    std::cout << std::setw(5) << rank << " -> " << l2_dist;
382	                    if (rank >= 16) { std::cout << " (Truncated to 16 bits)"; }
383	                    std::cout << std::endl;
384	                }
385	                rank++;
386	            }
387	        }
388	    }
389	    else if (m_distanceMode == "L1")
390	    {
391	        if (m_verboseInit) std::cout << "--- [TSDF3D16] Using 16-bit L1 (Manhattan) distance masks." << std::endl;
392	    }
393	    else
394	    {
395	    	std::cerr << "[TSDF3D16] Warning: distance_mode '" << m_distanceMode << "' not recognized. Defaulting to 'L1'." << std::endl;
396	    	m_distanceMode = "L1";
397	    }
398	
399		// --- Kernel Generation ---
400	    m_dirKernels.resize(m_numBins);
401	
402		const int kernel_total_voxels = m_kernelSize * m_kernelSize * m_kernelSize;
403	
404	    auto binToDir = [&](int az,int el) // <-- Añadido [&] para capturar 'this'
405	    {            
406	        float azr = (az+0.5f)*2.0f*M_PI / m_binsAz;
407	        float elr = (-M_PI/2)+ (el+0.5f)*M_PI / m_binsEl;
408	        float c   = cosf(elr);
409	        return Eigen::Vector3f(c*cosf(azr), c*sinf(azr), sinf(elr));
410	    };
411		
412	    for(int el=0; el < m_binsEl; ++el) 
413	    for(int az=0; az < m_binsAz; ++az) 
414	    {
415	        DirectionalKernel& DK = m_dirKernels[el*m_binsAz+az]; 
416	        Eigen::Vector3f dir = binToDir(az,el).normalized();
417	
418			DK.distance_masks.resize(kernel_total_voxels);
419	        DK.signs.resize(kernel_total_voxels);
420			
421	        int k=0;
422	        for(int z=-m_kernelRadius;z<=m_kernelRadius;++z) 
423	        for(int y=-m_kernelRadius;y<=m_kernelRadius;++y)
424	        for(int x=-m_kernelRadius;x<=m_kernelRadius;++x,++k)
425	        {       
426	            const float R_E = float(m_shadowRadiusMd); 
427	            float re2 = float(x*x + y*y + z*z); 
428	
429				// The Distance Mode "switch"
430	            if (m_distanceMode == "L1")
431	            {
432	                int l1_dist = std::abs(x) + std::abs(y) + std::abs(z);
433	                int   rd  = std::min(16, l1_dist);         
434	                uint16_t mask = (rd == 0) ? 0u : (0xFFFFu >> (16 - rd));
435	                DK.distance_masks[k] = mask;
436	            }
437	            else // "L2"
438	            {
439	                int r2_int = x*x + y*y + z*z; 
440	                DK.distance_masks[k] = m_r_squared_to_mask16[r2_int];
441	            }
442	            
443	            bool behind   = dir.dot(Eigen::Vector3f(x,y,z)) >= 0.0f;     
444	            const bool at_hit = (x == 0 && y == 0 && z == 0);
445	            bool inShadow = behind && (re2 <= R_E*R_E);                 
446	            DK.signs[k]   = (at_hit || inShadow) ? 0 : 1; 
447	        }
448	
449			// --- Kernel preview (only with verbose_init) ---
450	        int az_ray_from_left = 0; // Azimuth bin 0 corresponde a +X
451	        int el_horizontal = m_binsEl / 2; // Bin de elevación central (horizontal)
452	
453	        if (m_verboseInit && el == el_horizontal && az == az_ray_from_left)
454	        {
455	            std::cout << "\n--- Kernel preview (+X Ray) [Z=0 Slice] ---" << std::endl;
456	            std::cout << "--- Rank " << m_distanceMode << " | Shadow Radius: " << m_shadowRadiusMd << " ---" << std::endl;
457	            std::cout << "Format: [Rank][Sign] (#=Occupied/Shadow, .=Free)\n" << std::endl;
458	            std::cout << " (Y+) \n" << "  ^ \n" << "  | \n";
459	            
460	            int z_central = 0;
461	            int iz = z_central + m_kernelRadius;
462	            
463	            for(int y = m_kernelRadius; y >= -m_kernelRadius; --y) { 
464	                int iy = y + m_kernelRadius; 
465	                std::cout << std::setw(2) << y << " | "; 
466	                for(int x = -m_kernelRadius; x <= m_kernelRadius; ++x) { 
467	                    int ix = x + m_kernelRadius;
468	                    int k_idx = (iz * m_kernelSize * m_kernelSize) + (iy * m_kernelSize) + ix;
469	                    uint16_t mask = DK.distance_masks[k_idx];
470	                    int rank = std::bitset<16>(mask).count();
471	                    uint8_t sign = DK.signs[k_idx];
472	                    char sign_char = (sign == 0) ? '#' : '.';
473	                    std::cout << " " << std::setw(2) << rank << sign_char;
474	                }
475	                std::cout << std::endl; 
476	            }
477	            
478	            std::cout << "   " << std::string(60, '-') << "> (X+)" << std::endl;
479	            std::cout << "     ";
480	            for(int x = -m_kernelRadius; x <= m_kernelRadius; ++x) {
481	                std::cout << " " << std::setw(3) << x;
482	            }
483	            std::cout << "\n---------------------------------------------------------------------\n" << std::endl;
484	        }
485	    }
486	}
487	
488	#endif

