416	                                const uint32_t hits = static_cast<uint32_t>(cell[j].hits);
417	
418	                                // >>> CAMBIO: escribir el CENTRO del vóxel en el CSV <<<
419	                                const float cx = x_voxel_min + half;
420	                                const float cy = y_voxel_min + half;
421	                                const float cz = z_voxel_min + half;
