454	    void exportMesh(const std::string& filename, float iso_level, int occ_min_hits){
455	        vtkSmartPointer<vtkAppendPolyData> appender =
456	            vtkSmartPointer<vtkAppendPolyData>::New();
457	
458	        const float BAND = 0.1f * _cellRes;
459	
460	        for (uint32_t cz = 0; cz < _gridSizeZ; ++cz)
461	        for (uint32_t cy = 0; cy < _gridSizeY; ++cy)
462	        for (uint32_t cx = 0; cx < _gridSizeX; ++cx)
463	        {
464	            const uint32_t i = cx + cy * _gridStepY + cz * _gridStepZ;
465	            VoxelData* cell = _grid[i];
466	
467	            if (cell == _dummy) continue;
468	
469	            vtkSmartPointer<vtkImageData> image = vtkSmartPointer<vtkImageData>::New();
470	            image->SetDimensions(_cellSizeX + 1, _cellSizeY + 1, _cellSizeZ + 1); 
471	            image->SetSpacing(_cellRes, _cellRes, _cellRes);
472	            const float x0 = _minX + static_cast<float>(cx);
473	            const float y0 = _minY + static_cast<float>(cy);
474	            const float z0 = _minZ + static_cast<float>(cz);
475	            image->SetOrigin(x0, y0, z0);
476	            image->AllocateScalars(VTK_FLOAT, 1);
477	            
478	            float *dest = static_cast<float*>(image->GetScalarPointer());
479	            bool has_occupied_voxels = false;
480	
481	            for (uint32_t vz = 0; vz < _cellSizeZ + 1; ++vz)
482	            for (uint32_t vy = 0; vy < _cellSizeY + 1; ++vy)
483	            for (uint32_t vx = 0; vx < _cellSizeX + 1; ++vx)
484	            {
485	                VoxelData vox = this->read(x0 + vx * _cellRes, 
486	                                           y0 + vy * _cellRes, 
487	                                           z0 + vz * _cellRes);
488	
489	                const uint64_t dist_rank = __builtin_popcount(vox.d);
490	                const bool enough_hits = (vox.hits >= occ_min_hits);
491	                const bool occupied = ((vox.s & 0x01u) == 0);
492	                const bool is_surface = (dist_rank <= 1); 
493	
494	                float sdf_value;
495	                if (!enough_hits) {
496	                    sdf_value = +BAND; 
497	                } else if (occupied) {
498	                    sdf_value = -BAND; 
499	                    has_occupied_voxels = true;
500	                } else {
501	                    sdf_value = +BAND; 
502	                }
503	                
504	                dest[vx + vy * (_cellSizeX + 1) + vz * (_cellSizeX + 1) * (_cellSizeY + 1)] = sdf_value;
505	            }
506	
507	            if (has_occupied_voxels)
508	            {
509	                auto smoother = vtkSmartPointer<vtkImageGaussianSmooth>::New();
510	                smoother->SetInputData(image);
511	                smoother->SetStandardDeviation(1.0);
512	                smoother->Update();
513	
514	                auto mc = vtkSmartPointer<vtkMarchingCubes>::New();
515	                mc->SetInputConnection(smoother->GetOutputPort());
516	                mc->SetValue(0, iso_level); 
517	                mc->Update();
518	
519	                appender->AddInputData(mc->GetOutput());
520	            }
521	        } 
522	
523	        std::cout << "[GRID16] Joining cell meshes...\n";
524	        appender->Update();
525	
526	        auto ext_pos = filename.find_last_of('.');
527	        std::string ext = (ext_pos==std::string::npos) ? "" : filename.substr(ext_pos+1);
528	
529	        if (ext == "stl") {
530	            auto writer = vtkSmartPointer<vtkSTLWriter>::New();
531	            writer->SetFileName(filename.c_str());
532	            writer->SetInputData(appender->GetOutput());
533	            writer->SetFileTypeToBinary();  
534	            if (!writer->Write()) {
535	              throw std::runtime_error("VTK STL writer failed to write mesh.");
536	            }
537	        }
538	        else if (ext == "vtp") {
539	            auto writer = vtkSmartPointer<vtkXMLPolyDataWriter>::New();
540	            writer->SetFileName(filename.c_str());
541	            writer->SetInputData(appender->GetOutput());
542	            if (!writer->Write()) {
543	              throw std::runtime_error("VTK XML writer failed to write mesh.");
544	            }
545	        }
546	        else {
547	            throw std::invalid_argument("Unsupported file extension: " + ext);
548	        }
549	    }
