 38	
 39		struct Iterator
 40	    {
 41	        Iterator(GRID32* parent, VoxelData **grid, uint32_t i, uint32_t base, uint32_t j, uint32_t cellSizeX) 
 42	        { 
 43	            _parent = parent;
 44	            _grid = grid; 
 45	            _i = i;
 46	            _j = j;
 47	            _base = base;
 48	            _cellSizeX = cellSizeX;
