 53	        { 
 54	            _grid = it._grid; 
 55	            _i = it._i;
 56	            _j = it._j;
 57	            _base = it._base;
 58	            _cellSizeX = it._cellSizeX;
 59	            _curr = it._curr;
 60	            return *this;
 61	        }
 62	
 63	        VoxelData &operator*() { 
 64	            if (_curr == _parent->_dummy) {
 65	                return _parent->_garbage; 
 66	            }
 67	            return _curr[_j+_base]; 
 68	        }
 69	
 70	        VoxelData *operator->() { 
 71	            if (_curr == _parent->_dummy) {
 72	                return &(_parent->_garbage);
 73	            }
 74	            return _curr + _j + _base; 
 75	        }
