120			_minX = (int)floor(minX);
121			_minY = (int)floor(minY);
122			_minZ = (int)floor(minZ);
123	        
124			// Memory allocation for the world grid. It is initialized to 0 (NULL)
125			_gridSizeX = abs(_maxX-_minX);
126			_gridSizeY = abs(_maxY-_minY);
127			_gridSizeZ = abs(_maxZ-_minZ);
128			_gridStepY = _gridSizeX;
129			_gridStepZ = _gridSizeX*_gridSizeY;
130			_gridSize = _gridSizeX*_gridSizeY*_gridSizeZ;
131	        
132	        // Memory allocation for maxCells
133	        _maxCells = (uint64_t)maxCells;
134	        _cellRes = cellRes;
135	        _oneDivRes = 1.0/_cellRes;
136	        _cellSizeX = (uint32_t)_oneDivRes;
137	        _cellSizeY = (uint32_t)_oneDivRes;
138	        _cellSizeZ = (uint32_t)_oneDivRes;
139	        _cellStepY = _cellSizeX;
140	        _cellStepZ = _cellSizeX*_cellSizeY;
141	        _cellSize = 1 + static_cast<uint64_t>(_cellSizeX)*_cellSizeY*_cellSizeZ;  // The 1 is to store control information of the cell
142	        _buffer = (VoxelData *)malloc(_maxCells*_cellSize*sizeof(VoxelData)); // Circular buffer to store all cell masks
143	        std::memset(_buffer, -1, _maxCells*_cellSize*sizeof(VoxelData));     // Init the buffer to longest distance
144	        for(int i=0; i<_maxCells; i++)
145	        {
146				// _buffer[i*_cellSize] = VoxelData{static_cast<uint64_t>(_gridSize), 0xFF, 0xFF};
147	            uint32_t* control_index_ptr = reinterpret_cast<uint32_t*>(&_buffer[i*_cellSize]);
148	            *control_index_ptr = _gridSize;
149	        }
150	        _cellIndex = 0;
151	
152			_dummy = (VoxelData*)malloc(_cellSize * sizeof(VoxelData));
153			std::memset(_dummy, -1, _cellSize * sizeof(VoxelData));
154			// _dummy[0] = VoxelData{static_cast<uint64_t>(_gridSize), 0xFF, 0xFF};
155	        uint32_t* dummy_index_ptr = reinterpret_cast<uint32_t*>(&_dummy[0]);
156	        *dummy_index_ptr = _gridSize;
157	        _grid = (VoxelData**)malloc(_gridSize * sizeof(VoxelData*));
158	        for (uint32_t k = 0; k < _gridSize; ++k) _grid[k] = _dummy;
