   334	inline int TSDF3D32::dirToBin(const Eigen::Vector3f &v) const
   335	{
   336		float az = std::atan2(v.y(), v.x());
   337		if (az < 0) 
   338		{
   339			az += 2.0f*M_PI;
   340		}
