   342		float el  = std::asin(v.z() / v.norm());
   343		int   baz = int(az * m_binsAz / (2.0f*M_PI));
   344	    int   bel = int((el + M_PI/2) * m_binsEl / M_PI);
   345	
   346	    bel = std::clamp(bel, 0, m_binsEl - 1);
   347	    baz = std::clamp(baz, 0, m_binsAz - 1);
   348	
   349	    return bel*m_binsAz + baz;    
