   353	inline void TSDF3D32::initDirectionalKernels()
   354	{
   355	    if (m_distanceMode == "L2")
   356	    {
   357	        std::cout << "--- [TSDF3D32] Generating 32-bit L2 (Euclidean) distance LUT..." << std::endl;
   358	        if (m_r_squared_to_mask32.empty())
   359	        {
   360	            std::set<int> unique_r_squared;
   361	            for (int z = -m_kernelRadius; z <= m_kernelRadius; ++z) 
   362	                for (int y = -m_kernelRadius; y <= m_kernelRadius; ++y)
   363	                    for (int x = -m_kernelRadius; x <= m_kernelRadius; ++x)
   364	                    {
   365	                        unique_r_squared.insert(x*x + y*y + z*z);
   366	                    }
   367	
   368	            m_r_squared_to_mask32.clear();
   369	            uint32_t rank = 0; 
   370	            
   371	            std::cout << "---Rank -> L2 Distance (Voxels)" << std::endl;
   372	            for (int r2 : unique_r_squared)
   373	            {
   374	                uint32_t mask;
   375	                if (rank == 0)      { mask = 0u; }
   376	                else if (rank < 32) { mask = (0xFFFFFFFFu >> (32 - rank)); }
   377	                else                { mask = 0xFFFFFFFFu; } 
   378	                m_r_squared_to_mask32[r2] = mask;
   379	                float l2_dist = std::sqrt(static_cast<float>(r2));
   380	                std::cout << std::setw(5) << rank << " -> " << l2_dist;
   381	                if (rank >= 32) { std::cout << " (Truncated to 32 bits)"; }
   382	                std::cout << std::endl;
   383	                rank++;
   384	            }
   385	        }
   386	    }
   387	    else if (m_distanceMode == "L1")
   388	    {
   389	        std::cout << "--- [TSDF3D32] Using 32-bit L1 (Manhattan) distance masks." << std::endl;
   390	    }
   391	    else
   392	    {
   393	    	std::cerr << "[TSDF3D32] Warning: distance_mode '" << m_distanceMode << "' not recognized. Defaulting to 'L1'." << std::endl;
   394	    	m_distanceMode = "L1";
   395	    }
   396	
   397		// --- Kernel Generation ---
   398	    m_dirKernels.resize(m_numBins);
   399	
   400		const int kernel_total_voxels = m_kernelSize * m_kernelSize * m_kernelSize;
   401	
   402	    auto binToDir = [&](int az,int el) // <-- Añadido [&] para capturar 'this'
   403	    {            
   404	        float azr = (az+0.5f)*2.0f*M_PI / m_binsAz;
   405	        float elr = (-M_PI/2)+ (el+0.5f)*M_PI / m_binsEl;
   406	        float c   = cosf(elr);
   407	        return Eigen::Vector3f(c*cosf(azr), c*sinf(azr), sinf(elr));
   408	    };
   409		
   410	    for(int el=0; el < m_binsEl; ++el) 
   411	    for(int az=0; az < m_binsAz; ++az) 
   412	    {
   413	        DirectionalKernel& DK = m_dirKernels[el*m_binsAz+az]; 
   414	        Eigen::Vector3f dir = binToDir(az,el).normalized();
   415	
   416			DK.distance_masks.resize(kernel_total_voxels);
   417	        DK.signs.resize(kernel_total_voxels);
   418			
   419	        int k=0;
   420	        for(int z=-m_kernelRadius;z<=m_kernelRadius;++z) 
   421	        for(int y=-m_kernelRadius;y<=m_kernelRadius;++y)
   422	        for(int x=-m_kernelRadius;x<=m_kernelRadius;++x,++k)
   423	        {       
   424	            const float R_E = float(m_shadowRadiusMd); 
   425	            float re2 = float(x*x + y*y + z*z); 
   426	
   427				// The Distance Mode "switch"
   428	            if (m_distanceMode == "L1")
   429	            {
   430	                int l1_dist = std::abs(x) + std::abs(y) + std::abs(z);
   431	                int   rd  = std::min(32, l1_dist);         
   432	                uint32_t mask = (rd == 0) ? 0u : (0xFFFFFFFFu >> (32 - rd));
   433	                DK.distance_masks[k] = mask;
   434	            }
   435	            else // "L2"
   436	            {
   437	                int r2_int = x*x + y*y + z*z; 
   438	                DK.distance_masks[k] = m_r_squared_to_mask32[r2_int];
   439	            }
   440	            
   441	            bool behind   = dir.dot(Eigen::Vector3f(x,y,z)) >= 0.0f;     
   442	            const bool at_hit = (x == 0 && y == 0 && z == 0);
   443	            bool inShadow = behind && (re2 <= R_E*R_E);                 
   444	            DK.signs[k]   = (at_hit || inShadow) ? 0 : 1; 
   445	        }
