 37	// 8-byte voxel record
 38	struct VoxelData
 39	{
 40		uint32_t d;		// Manhattan mask (bit-count -> distance)
 41		uint8_t s;		// bit0: sign (0 occ / 1 free)
 42		uint16_t hits;	// hit counter
