 70			m_gridSizeZ = fabs(m_maxZ-m_minZ)*m_oneDivRes;
 71			m_gridStepY = m_gridSizeX;
 72			m_gridStepZ = m_gridSizeX*m_gridSizeY;
 73			m_gridSize = m_gridSizeX*m_gridSizeY*m_gridSizeZ;
 74			m_gridData = (VoxelData *)malloc(m_gridSize*sizeof(VoxelData));
