 96		{
 97			for (uint64_t i = 0; i < m_gridSize; ++i)
 98			{
 99				m_gridData[i].d = 0xFFFFFFFFu;   // bits set to 1 → distance 32
100				m_gridData[i].s = 1;             // 1 = free
101				m_gridData[i].hits = 0; 
