149		// Dense TSDF update using 21³ directional kernels around each point
150		void loadCloud(std::vector<pcl::PointXYZ> &cloud)
151		{
152			const auto t0 = std::chrono::steady_clock::now();
153			const float step = 10 * m_resolution;			// 20-voxel cube
154	
155			#pragma omp parallel for num_threads(20) shared(m_dirKernels, m_gridData) 
156			for(uint32_t i=0; i<cloud.size(); i++)
157			{
158	        	// Skip if 21³ neighborhood falls outside the grid
159				if(!isIntoGrid(cloud[i].x-step, cloud[i].y-step, cloud[i].z-step) || 
160				   !isIntoGrid(cloud[i].x+step, cloud[i].y+step, cloud[i].z+step))
161					continue;
162				
163				// Select kernel by ray direction
164				Eigen::Vector3f dir(cloud[i].x, cloud[i].y, cloud[i].z);
165	    		const DirectionalKernel& DK = m_dirKernels[dirToBin(dir)];
166	
167				// Convolve neighborhood
168				int xi, yi, zi, k = 0;
169				uint64_t idx, idy, idz = pointToGrid(cloud[i].x-step, cloud[i].y-step, cloud[i].z-step);
170				for(zi=0; zi<21; zi++, idz+=m_gridStepZ)
171					for(yi=0, idy=idz; yi<21; yi++, idy+=m_gridStepY)
172						for(xi=0, idx=idy; xi<21; xi++, k++, idx++)
173						{
174							uint32_t old_mask = m_gridData[idx].d;                    
175							uint32_t new_mask = old_mask & DK.distance_masks[k];
176							
177							if (new_mask != old_mask)
178								m_gridData[idx].d = new_mask;
179	
180							if (DK.signs[k] == 0) { // occupied evidence
181								if (m_gridData[idx].hits < std::numeric_limits<uint16_t>::max()) 
182									++m_gridData[idx].hits;
183									if (m_gridData[idx].hits == OCC_MIN_HITS)
184										m_gridData[idx].s &= uint8_t(~0x01);   // bit0=0 → ocupado
185							}
186						}
187			}
188	
189			const auto t1 = std::chrono::steady_clock::now();
190			recordKernelTime(std::chrono::duration<double,std::milli>(t1 - t0).count());
191		}
