458		// Data
459		std::vector<pcl::PointXYZ>  m_last_corrected_cloud;		
460	
461		VoxelData *m_gridData;								 
462		
463		// Directional kernels
464		std::vector<DirectionalKernel> m_dirKernels;
465		inline int dirToBin(const Eigen::Vector3f &v) const;
466		void initDirectionalKernels();
467	
468		// Timing stats (printed every STAT_PERIOD frames)
469		static constexpr int  STAT_PERIOD = 50;
470		static inline std::atomic<uint64_t> s_frames{0};
471		static inline std::atomic<double>   s_sumMs{0.0};
472		static inline std::atomic<double>   s_sumSqMs{0.0};   		
473	
474		// Accumulate and log kernel timings
475		static inline void recordKernelTime(double ms)
476		{
477			uint64_t n = ++s_frames;         
478			s_sumMs   += ms;                 
479			s_sumSqMs += ms * ms;          
480	
481			if (n % STAT_PERIOD == 0)
482			{
483				const double mean = s_sumMs.load() / static_cast<double>(n);
484				const double var  = (s_sumSqMs.load() / static_cast<double>(n)) - mean * mean;
485				double stddev = std::sqrt(std::max(var, 0.0));
486	
487				RCLCPP_INFO(rclcpp::get_logger("tdf_time"),
488					"[32-bit]  %lu frames · mean = %.3f ms · σ = %.3f ms   (last = %.3f ms)",
489					n, mean, stddev, ms);
490			}
491		}
492	};
