494	// Map direction to bin index (azimuth × elevation)
495	inline int TDF3D32::dirToBin(const Eigen::Vector3f &v) const
496	{
497		float az = std::atan2(v.y(), v.x());
498		if (az < 0) az += 2.0f*M_PI;
499		float el = std::asin(v.z() / v.norm());
500	
501		int baz = int(az * BINS_AZ / (2.0f*M_PI));
502		int bel = int((el + M_PI/2) * BINS_EL / M_PI);
503		bel = std::clamp(bel, 0, BINS_EL-1);
504		baz = std::clamp(baz, 0, BINS_AZ-1);
505	
506		return bel*BINS_AZ + baz;          
507	}
508	
509	// Build 40×40 directional kernels (21³ window per bin)
510	inline void TDF3D32::initDirectionalKernels()
511	{
512		m_dirKernels.resize(NUM_BINS);
513	
514		auto binToDir = [](int az,int el){			 
515			float azr = (az+0.5f)*2.0f*M_PI/BINS_AZ;
516			float elr = (-M_PI/2)+ (el+0.5f)*M_PI/BINS_EL;
517			float c = cosf(elr);
518			return Eigen::Vector3f(c*cosf(azr), c*sinf(azr), sinf(elr));
519		};
520	
521		for(int el=0; el<BINS_EL; ++el)
522		for(int az=0; az<BINS_AZ; ++az)
523		{
524			DirectionalKernel& DK = m_dirKernels[el*BINS_AZ+az];
525			Eigen::Vector3f dir = binToDir(az,el).normalized();
526	
527			int k=0;
528			for(int z=-10;z<=10;++z)
529			for(int y=-10;y<=10;++y)
530			for(int x=-10;x<=10;++x,++k)
531			{       
532				constexpr float R_E = float(SHADOW_RADIUS_MD); 
533	
534				float re2 = float(x*x + y*y + z*z);            
535				float re  = std::sqrt(re2);
536				int   rd  = std::min(32, int(std::ceil(re)));   
537	
538				uint32_t mask = (rd == 0) ? 0u : (0xFFFFFFFFu >> (32 - rd));
539				DK.distance_masks[k] = mask;
540	
541				bool behind   = dir.dot(Eigen::Vector3f(x,y,z)) > 0.0f;     
542				const bool at_hit = (x == 0 && y == 0 && z == 0);
543				bool inShadow = behind && (re2 <= R_E*R_E);                 
544				DK.signs[k]   = (at_hit || inShadow) ? 0 : 1; 
545			}
546		}
547	}
