     1	// VTKMeshExtractor: Extract a surface mesh from a TDF grid using VTK.
     2	// Pipeline: TDF → vtkImageData → smoothing → Marching Cubes → mesh file.
     3	
     4	#include "mesh/vtk_mesh_extractor.hpp"
     5	#include <cstring> 
     6	
     7	constexpr float KEEP_RATIO = 0.00f;   // Ratio of max voxel hits used as hit threshold
     8	
     9	void VTKMeshExtractor::extract(const TDF3D32 &grid,
    10	                               const std::string &filename,
    11	                               float iso_level)
    12	{
    13	  // 1) Allocate VTK volume
    14	  auto image = vtkSmartPointer<vtkImageData>::New();
    15	  int nx = static_cast<int>(grid.getSizeX());
    16	  int ny = static_cast<int>(grid.getSizeY());
    17	  int nz = static_cast<int>(grid.getSizeZ());
    18	  image->SetDimensions(nx, ny, nz);
    19	  image->SetSpacing(grid.getResolution(), grid.getResolution(), grid.getResolution());
    20	  image->SetOrigin (grid.getMinX(),      grid.getMinY(),      grid.getMinZ());
    21	  image->AllocateScalars(VTK_FLOAT, 1);
    22	
    23	  // 2) Copy TDF values into VTK buffer
    24	  float *dest = static_cast<float*>(image->GetScalarPointer());
    25	  size_t count = static_cast<size_t>(nx) * ny * nz;
    26	  const float h = grid.getResolution();                      
    27	  const VoxelData *vox  = grid.getVoxelPtr();    
    28	
    29	  // 2.a) Compute hit threshold
    30	  uint8_t maxHits = 0;
    31	  for (size_t i = 0; i < count; ++i)
    32	      if (vox[i].hits > maxHits) maxHits = vox[i].hits;
    33	
    34	  const uint8_t thrHits =
    35	      (maxHits == 0) ? 255
    36	                    : static_cast<uint8_t>(std::round(maxHits * KEEP_RATIO));
    37	
    38	  // 2.b) Fill buffer with signed band values
    39	  const float BAND = 1.1f * h;  
    40	  for (size_t i = 0; i < count; ++i)
    41	  {
    42	      const float dvox = grid.voxelDist(i);   
    43	      const bool enough_hits = (vox[i].hits >= thrHits);
    44	      if (!enough_hits) {
    45	          dest[i] = +BAND;                 
    46	          continue;
    47	      }
    48	      const bool occupied = ((vox[i].s & 0x01) == 0); 
    49	      const bool is_center = (dvox == 0.0f);          
    50	      if (occupied && is_center) {
    51	          dest[i] = -BAND;                   
    52	      } else {
    53	          dest[i] = +BAND;               
    54	      }
    55	  }
    56	
    57	  // 2.5) Gaussian smoothing
    58	  auto smoother = vtkSmartPointer<vtkImageGaussianSmooth>::New();
    59	  smoother->SetInputData(image);
    60	  smoother->SetStandardDeviation(1.0);  
    61	  // smoother->SetRadiusFactors(1.5, 1.5, 1.5);
    62	  // smoother->SetDimensionality(3);
    63	  smoother->Update();
    64	
    65	  // 3) Marching Cubes extraction
    66	  auto mc = vtkSmartPointer<vtkMarchingCubes>::New();
    67	  mc->SetInputConnection(smoother->GetOutputPort());
    68	  mc->ComputeNormalsOn();
    69	  mc->SetValue(0, iso_level);
    70	  mc->Update();
    71	
    72	  // 4) Save mesh as STL or VTP  
    73	  auto ext_pos = filename.find_last_of('.');
    74	  std::string ext = (ext_pos==std::string::npos)
    75	                    ? ""
    76	                    : filename.substr(ext_pos+1);
    77	  if (ext == "stl") {
    78	    // Binary STL
    79	    auto writer = vtkSmartPointer<vtkSTLWriter>::New();
    80	    writer->SetFileName(filename.c_str());
    81	    writer->SetInputData(mc->GetOutput());
    82	    writer->SetFileTypeToBinary();  
    83	    if (!writer->Write()) {
    84	      throw std::runtime_error("VTK STL writer failed to write mesh.");
    85	    }
    86	  }
    87	  else if (ext == "vtp") {
    88	    // VTP XML
    89	    auto writer = vtkSmartPointer<vtkXMLPolyDataWriter>::New();
    90	    writer->SetFileName(filename.c_str());
    91	    writer->SetInputData(mc->GetOutput());
    92	    if (!writer->Write()) {
    93	      throw std::runtime_error("VTK XML writer failed to write mesh.");
    94	    }
    95	  }
    96	  else {
    97	    throw std::invalid_argument(
    98	      "Unsupported file extension: " + ext + 
    99	      " (only .stl and .vtp are supported)");
   100	  }
   101	}
