cat > /tmp/claude-1000/-home-jcrex-Proyectos-PSVita-ROS/d90a8c2e-dd6b-4dea-8c32-fe21a8477ad2/scratchpad/scripts/kernel_stats.py <<'EOF'
# Estadísticas de kernels DB-TSDF (reimplementación propia de las fórmulas leídas en
# tsdf3d_16.hpp:352-447 y legacy tsdf3d_32.hpp:528-545; NO ejecuta código del repo ajeno).
import math, itertools

def levels_L1(K, W):
    R = (K - 1) // 2
    out = {}
    for z, y, x in itertools.product(range(-R, R + 1), repeat=3):
        out[(x, y, z)] = min(W, abs(x) + abs(y) + abs(z))
    return out

def levels_L2rank(K, W):
    R = (K - 1) // 2
    uniq = sorted({x*x + y*y + z*z for z, y, x in itertools.product(range(-R, R + 1), repeat=3)})
    rank = {r2: i for i, r2 in enumerate(uniq)}
    out = {}
    for z, y, x in itertools.product(range(-R, R + 1), repeat=3):
        r = rank[x*x + y*y + z*z]
        out[(x, y, z)] = r if r < W else W
    return out, uniq

def levels_ceilL2(K, W):
    R = (K - 1) // 2
    out = {}
    for z, y, x in itertools.product(range(-R, R + 1), repeat=3):
        out[(x, y, z)] = min(W, math.ceil(math.sqrt(x*x + y*y + z*z)))
    return out

print("== Kernel: niveles distintos usados y entradas no-op (nivel == W) ==")
print(f"{'K':>3} {'W':>3} {'modo':>8} {'K^3':>6} {'niveles<W':>10} {'max nivel':>9} {'noop':>6} {'noop%':>6} {'sin pérdida':>11}")
for K in (3, 5, 7, 9, 11, 13, 21, 25):
    for W in (4, 8, 16, 32):
        for mode in ("L1", "L2rank", "ceilL2"):
            if mode == "L1":
                lv = levels_L1(K, 10**6); lvW = levels_L1(K, W)
            elif mode == "L2rank":
                lv, _ = levels_L2rank(K, 10**6); lvW, _ = levels_L2rank(K, W)
            else:
                lv = levels_ceilL2(K, 10**6); lvW = levels_ceilL2(K, W)
            full_max = max(lv.values())
            noop = sum(1 for v in lvW.values() if v >= W)
            used = len({v for v in lvW.values() if v < W})
            lossless = full_max < W
            print(f"{K:>3} {W:>3} {mode:>8} {K**3:>6} {used:>10} {full_max:>9} {noop:>6} {100*noop/K**3:>5.1f}% {'sí' if lossless else 'no':>11}")

print()
print("== K máximo sin pérdida por W ==")
for W in (2, 4, 8, 16, 32):
    row = []
    for mode in ("L1", "L2rank", "ceilL2"):
        best = 1
        for K in range(1, 64, 2):
            if mode == "L1":
                m = max(levels_L1(K, 10**6).values())
            elif mode == "L2rank":
                m = max(levels_L2rank(K, 10**6)[0].values())
            else:
                m = max(levels_ceilL2(K, 10**6).values())
            if m < W:
                best = K
            else:
                break
        row.append(f"{mode}: K<={best}")
    print(f"W={W:>2}: " + "  ".join(row))

print()
print("== L2rank: distancia (vóxeles) del último rango representable ==")
for K, W in ((3,4),(5,8),(5,16),(7,16),(11,16),(13,32),(21,32),(25,32)):
    lv, uniq = levels_L2rank(K, W)
    last = min(W - 1, len(uniq) - 1)
    print(f"K={K:>2} W={W:>2}: rangos distintos en el cubo={len(uniq):>3}; último rango útil={last} -> r2={uniq[last]} (d={math.sqrt(uniq[last]):.2f} vóx)")

print()
print("== Sombra: nº de entradas con signo 0 (hemisferio L2 radio rs recortado al cubo), dir=+x ==")
for K, rs in ((3,1),(3,5),(5,2),(5,5),(7,3),(7,5),(11,5),(21,8),(25,10)):
    R = (K - 1)//2
    n = 0
    for z, y, x in itertools.product(range(-R, R + 1), repeat=3):
        behind = (1.0*x) >= 0.0
        if (x == 0 and y == 0 and z == 0) or (behind and (x*x+y*y+z*z) <= rs*rs):
            n += 1
    print(f"K={K:>2} rs={rs:>2}: {n:>5} de {K**3} ({100*n/K**3:.1f}%)")
